insert into public.tests (id, slug, title, subtitle, test_type, section_scope, focus_domain_id, difficulty, description, sort_order) values ('b0cdfd99-f9e4-5eee-a7cb-b447f51d0592', 'full-mock-3', 'Full Mock 3', 'End-of-week check — official question mix', 'full_mock', 'both', null, 'hard', 'Four timed parts: two Reading and Writing modules of 27 questions and two Math modules of 22 questions. Same difficulty as Mock 2, with Conventions at the level of the official test. Take it in one sitting.', 3) on conflict (slug) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 'b0cdfd99-f9e4-5eee-a7cb-b447f51d0592', 1, 'Reading and Writing — Module 1', 'rw', 1920) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('156d2409-48a1-5622-ad3d-6cd60c4172ee', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 1, 'craft_structure', 'words_in_context', 'easy', 'mc', 'Ice cores drilled from Antarctic glaciers hold air bubbles trapped for hundreds of thousands of years. Because each layer of snow sealed in a sample of the atmosphere as it fell, the cores provide an unusually _______ record of past carbon dioxide levels, one that does not depend on indirect estimates.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"contested"},{"key":"B","text":"brief"},{"key":"C","text":"direct"},{"key":"D","text":"ornate"}]'::jsonb, 'C', null, 'The final clause defines the blank by contrast: a record that ''does not depend on indirect estimates'' is a direct one. ''Brief'' is the trap for a reader who skims ''sample,'' but the cores span hundreds of thousands of years, the opposite of brief.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('95376114-ca6a-540b-a876-99d6e38c35fb', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 2, 'craft_structure', 'words_in_context', 'easy', 'mc', 'The architect''s first designs for the library were praised for their ambition but rejected as _______: the cantilevered reading rooms alone would have cost three times the city''s entire budget.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"conventional"},{"key":"B","text":"derivative"},{"key":"C","text":"modest"},{"key":"D","text":"impractical"}]'::jsonb, 'D', null, 'The colon explains the rejection with a cost three times the budget, so the designs could not be carried out: impractical. ''Modest'' and ''conventional'' contradict ''ambition,'' and ''derivative'' (copied) has no support in the text.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('0b51e0a9-ff7e-5304-a806-b5235d3f12a4', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 3, 'craft_structure', 'text_structure_purpose', 'easy', 'mc', 'Mangrove forests grow where rivers meet the sea, in water too salty for most trees. Their tangled roots slow incoming waves, trapping sediment and building up the shoreline over time. For coastal towns, this makes a mangrove belt a living seawall, one that repairs itself after a storm, which no concrete wall can do.', 'Which choice best describes the function of the third sentence in the text as a whole?', '[{"key":"A","text":"It presents a practical benefit that follows from the process described in the second sentence."},{"key":"B","text":"It explains why mangroves can survive in salt water."},{"key":"C","text":"It introduces a counterargument to the claim that mangroves protect shorelines."},{"key":"D","text":"It compares the cost of planting mangroves with the cost of building concrete walls."}]'::jsonb, 'A', null, 'Sentence two describes what the roots do; sentence three draws out what that means for towns, a self-repairing seawall. Choice D is the trap: concrete walls are mentioned, but for what they cannot do, not for what they cost.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('cd54038b-3102-50a3-a644-8c71d205e802', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 4, 'craft_structure', 'words_in_context', 'medium', 'mc', 'Beatrix Potter is remembered for her children''s books, yet her early study of fungi was serious enough that a paper of hers was read to the Linnean Society in 1897. Historians now describe her hundreds of mycological drawings as _______, recording spore structures with a precision the amateur sketches of the period rarely matched.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"whimsical"},{"key":"B","text":"meticulous"},{"key":"C","text":"rudimentary"},{"key":"D","text":"derivative"}]'::jsonb, 'B', null, 'The clue is ''a precision the amateur sketches of the period rarely matched,'' which calls for extremely careful work: meticulous. ''Whimsical'' is the trap set by her fame for children''s books; the sentence is explicitly contrasting that reputation with her scientific rigor.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('c600aaff-4a88-5d3d-adf3-bdcdfc19bf56', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 5, 'craft_structure', 'text_structure_purpose', 'medium', 'mc', 'For much of the twentieth century, the standard explanation for the Moon''s craters was volcanic. In 1960, geologist Eugene Shoemaker showed that Meteor Crater in Arizona contained minerals that form only under the sudden, extreme pressure of an impact, not the slow heat of an eruption. Within a decade, impact had replaced eruption as the accepted origin of nearly every lunar crater.', 'Which choice best describes the overall structure of the text?', '[{"key":"A","text":"Two competing theories are compared, and both are rejected."},{"key":"B","text":"A discovery is described, and its practical applications are listed."},{"key":"C","text":"A hypothesis is proposed, and an experiment to test it is outlined."},{"key":"D","text":"A long-held explanation is stated, evidence against it is presented, and the resulting shift in scientific opinion is noted."}]'::jsonb, 'D', null, 'The passage moves from the old view (volcanic) to contrary evidence (Shoemaker''s minerals) to the new consensus (impact). Choice A is the trap: there are two theories, but only one is rejected, and the other wins.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('026162c0-531c-51b7-af7a-4d461a9e5ccf', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 6, 'craft_structure', 'words_in_context', 'hard', 'mc', 'Critics expected the novelist''s memoir to settle the long debate over which events in her fiction were drawn from life. Instead, the book is deliberately _______: it narrates the same childhood summer three times, each version contradicting the last, and never says which one is true.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"equivocal"},{"key":"B","text":"exhaustive"},{"key":"C","text":"candid"},{"key":"D","text":"nostalgic"}]'::jsonb, 'A', null, 'Three contradictory versions with no verdict make the book noncommittal, or equivocal. ''Candid'' is the trap, since memoirs are expected to be frank, but a book that refuses to say what is true is the opposite of candid.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('8bf81d97-b738-5f8c-a7a2-a5ebdb676e76', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 7, 'craft_structure', 'text_structure_purpose', 'hard', 'mc', 'The letter had been in the drawer for eleven years, and in all that time Teodros had not opened it. He knew what it said; his mother had told him, more than once, the afternoon she wrote it. What he did not know was whether he would still recognize her handwriting, and it was this, not the words, that kept the drawer shut.', 'Which choice best states the main purpose of the text?', '[{"key":"A","text":"To explain the contents of a letter that a character has refused to read"},{"key":"B","text":"To show that a character resents his mother for a message she left him"},{"key":"C","text":"To suggest that a character avoids the letter out of fear about his own fading memory of his mother, not because of what it says"},{"key":"D","text":"To describe the drawer and the room in which a letter has been kept"}]'::jsonb, 'C', null, 'The last sentence names the real obstacle: ''whether he would still recognize her handwriting,'' and then insists ''it was this, not the words.'' Choice A reverses the emphasis, since the passage says he already knows the contents and that they are not the issue.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('e9b4a3ae-e312-5a24-a60a-26add1d24a9b', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 8, 'craft_structure', 'cross_text_connections', 'hard', 'mc', 'Text 1
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('17576f41-6929-56ea-aeb9-7c0d66233d88', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 9, 'information_ideas', 'central_ideas_details', 'easy', 'mc', 'Before mechanical refrigeration, ice was a global commodity. In the 1830s Frederic Tudor''s company cut ice from ponds near Boston, packed it in sawdust, and shipped it as far as Calcutta, where it sold at a profit even though much of each cargo melted on the way. The insulated icehouses built at ports to store it were the direct ancestors of the modern cold-storage warehouse.', 'Which choice best states the main idea of the text?', '[{"key":"A","text":"Frederic Tudor''s ice business failed because most of each cargo melted before arrival."},{"key":"B","text":"The nineteenth-century ice trade carried natural ice across enormous distances and laid the groundwork for modern cold storage."},{"key":"C","text":"Boston was the most important port in the world during the 1830s."},{"key":"D","text":"Mechanical refrigeration was invented to replace the unreliable ice trade."}]'::jsonb, 'B', null, 'The passage describes the trade''s reach and then its legacy in the final sentence, which choice B captures. Choice A is the trap: melting is mentioned, but the ice still ''sold at a profit,'' so the business did not fail.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('ef4bb6ae-668c-5ef3-a00e-24b93c66988a', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 10, 'information_ideas', 'evidence_textual', 'easy', 'mc', 'Sperm whales communicate in patterned sequences of clicks, and different clans use noticeably different rhythms. Some researchers believe these rhythms function partly as identity signals, like a dialect. If so, whales should respond differently to clicks from their own clan than to clicks from others.', 'Which finding, if true, would most directly support the researchers'' belief?', '[{"key":"A","text":"Sperm whales produce clicks across a wider range of frequencies than earlier studies measured."},{"key":"B","text":"Clans living in different oceans hunt different species of squid."},{"key":"C","text":"Whales approached underwater speakers playing their own clan''s click patterns but moved away from speakers playing other clans'' patterns."},{"key":"D","text":"Young sperm whales produce fewer clicks per minute than adults do."}]'::jsonb, 'C', null, 'The passage sets up a test in its last sentence, and choice C reports exactly that result: different behavior toward own-clan and other-clan clicks. The other choices describe whale sounds or habits but say nothing about whether clicks mark identity.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('211a6e67-e9c8-5867-ab7f-65046743ee77', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 11, 'information_ideas', 'evidence_quantitative', 'easy', 'mc', 'A school tracked the number of library books borrowed per student each year.
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('12cc7e2b-e7e2-51ff-a9cb-5fcf5c0f474e', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 12, 'information_ideas', 'central_ideas_details', 'medium', 'mc', 'My grandfather kept bees the way other men kept secrets: without discussing it, and with a patience that seemed to cost him nothing. In the mornings he would stand at the hives bareheaded, and the bees would walk across his hands as if he were a fence post. I asked him once whether he was ever afraid. He said fear was a smell, and that he had simply learned not to make it.', 'Which choice best states the main idea of the text?', '[{"key":"A","text":"The narrator''s grandfather concealed important family matters from his relatives."},{"key":"B","text":"Beekeeping is dangerous and should be done with protective clothing."},{"key":"C","text":"The narrator hoped to take over the grandfather''s hives one day."},{"key":"D","text":"The narrator''s grandfather had a calm, almost instinctive ease with his bees that the narrator found remarkable."}]'::jsonb, 'D', null, 'Every detail, from the bare head to the bees treating him like a fence post to his answer about fear, builds a portrait of unforced calm. Choice A takes the opening comparison literally; ''the way other men kept secrets'' describes his quiet manner, not actual secrets.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('6def4ae8-0d4b-589f-a17b-39f7c26e5875', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 13, 'information_ideas', 'inferences', 'medium', 'mc', 'Homing pigeons released hundreds of kilometers from their loft return reliably, and for decades the leading explanation was that they navigate by the Sun. Yet pigeons also find their way home on heavily overcast days, and birds fitted with frosted lenses that blur everything beyond a few meters still arrive at their lofts. This suggests that _______', 'Which choice most logically completes the text?', '[{"key":"A","text":"pigeons rely mainly on recognizing landmarks along the route."},{"key":"B","text":"pigeons are unable to navigate when the Sun is hidden."},{"key":"C","text":"pigeons use at least one navigational cue that does not require a clear view of the Sun or the landscape."},{"key":"D","text":"frosted lenses sharpen a pigeon''s sense of direction."}]'::jsonb, 'C', null, 'Overcast skies remove the Sun and frosted lenses remove the landscape, yet the birds still get home, so some other cue must exist. Choice A is the trap: blurred vision rules out landmark recognition rather than supporting it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('45cdbba2-c584-5001-a47e-efc38ef15950', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 14, 'information_ideas', 'evidence_textual', 'hard', 'mc', 'A historian argues that mass-produced cast-iron cooking stoves spread rapidly across rural New England in the 1840s mainly because they burned far less wood than open hearths, a decisive advantage in districts where woodlots were shrinking.', 'Which finding, if true, would most directly weaken the historian''s argument?', '[{"key":"A","text":"Most stove manufacturers of the 1840s were located in Pennsylvania rather than in New England."},{"key":"B","text":"Cast-iron stoves were also sold in large numbers in cities."},{"key":"C","text":"Open hearths continued to be used for some cooking tasks even in homes that owned a stove."},{"key":"D","text":"Stoves sold fastest in the heavily forested counties where firewood remained cheap and abundant."}]'::jsonb, 'D', null, 'The argument rests on fuel scarcity driving sales; if sales were strongest where wood was plentiful, scarcity cannot be the main reason. Choice C is the trap: continued hearth use does not touch the question of why stoves spread quickly.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('b352ae57-02f8-5c92-a3f2-eff6102659e3', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 15, 'information_ideas', 'inferences', 'hard', 'mc', 'Medieval parchment was made from animal skin, and traces of the animal''s DNA survive in the pages. Sampling hundreds of legal deeds from one English region, researchers found that the skins came overwhelmingly from local sheep rather than from the calfskin preferred for luxury manuscripts. Since a legal deed had to be durable but not beautiful, the finding implies that _______', 'Which choice most logically completes the text?', '[{"key":"A","text":"medieval scribes preferred sheepskin for every type of document."},{"key":"B","text":"the choice of animal skin was governed by cost and purpose rather than by prestige."},{"key":"C","text":"calfskin manuscripts were produced only in regions that had no sheep."},{"key":"D","text":"English legal documents from the period were rarely preserved."}]'::jsonb, 'B', null, 'Cheap local sheepskin for plain, durable deeds and calfskin for luxury books is a pattern of matching material to purpose and budget. Choice A overreaches: the passage itself says calfskin was preferred for luxury manuscripts, so sheepskin was not used for everything.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('32b9122a-b3f3-51c6-a5bc-ba008053525d', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 16, 'standard_conventions', 'boundaries', 'easy', 'mc', 'The Sahel''s Great Green Wall was conceived in 2007 as a continuous band of trees across _______ has since become a mosaic of local projects, from drought-resistant orchards to restored grazing land.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"Africa; it"},{"key":"B","text":"Africa, it"},{"key":"C","text":"Africa it"},{"key":"D","text":"Africa, and, it"}]'::jsonb, 'A', null, '''The Great Green Wall was conceived as a band of trees across Africa'' and ''it has since become a mosaic'' are both complete sentences, so a semicolon joins them. Choice B is a comma splice, choice C a run-on, and choice D wraps ''and'' in commas that do not belong.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('faba581e-4b37-5c44-a0a8-98a711ebc8e2', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 17, 'standard_conventions', 'form_structure_sense', 'easy', 'mc', 'Each of the radio telescopes in the array, spread across a high plateau in northern Chile, _______ its own cooling system.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"requires"},{"key":"B","text":"require"},{"key":"C","text":"are requiring"},{"key":"D","text":"have required"}]'::jsonb, 'A', null, 'The subject is ''Each,'' which is always singular, so the verb is ''requires.'' The plural ''telescopes'' and the long interrupting phrase are placed next to the blank to pull the ear toward ''require.''') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('6c7d6fc1-5616-5991-a4ff-cadda1f90394', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 18, 'standard_conventions', 'boundaries', 'medium', 'mc', 'The expedition''s survey of the cave turned up three species previously unknown to _______ a blind beetle, a translucent shrimp, and a fungus that glows faintly in the dark.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"science;"},{"key":"B","text":"science."},{"key":"C","text":"science:"},{"key":"D","text":"science"}]'::jsonb, 'C', null, 'The words before the blank form a complete sentence and the words after it are the list that explains it, which is exactly what a colon introduces. A semicolon or period would leave the list stranded as a fragment with no verb.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('128e1706-326d-5461-aa5a-aba677b478b7', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 19, 'standard_conventions', 'boundaries', 'medium', 'mc', 'The question of whether the city''s medieval walls should be rebuilt or left as picturesque _______ divided the council for a decade.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"ruins, has"},{"key":"B","text":"ruins has"},{"key":"C","text":"ruins; has"},{"key":"D","text":"ruins — has"}]'::jsonb, 'B', null, 'The subject is ''The question'' and ''has divided'' is its verb; nothing may separate a subject from its verb, however long the subject runs. The comma in choice A is the natural breath after a long subject, which is precisely the trap.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('1afe7541-cb1c-5601-a1f8-f51493e90894', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 20, 'standard_conventions', 'form_structure_sense', 'medium', 'mc', '_______ engineers replaced the bridge''s steel cables one at a time so that traffic never had to stop.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"Corroded by decades of salt spray,"},{"key":"B","text":"Corroding in decades of salt spray,"},{"key":"C","text":"Having been corroded by decades of salt spray,"},{"key":"D","text":"Finding the cables corroded by decades of salt spray,"}]'::jsonb, 'D', null, 'An opening phrase must describe the noun that follows the comma, and that noun is ''engineers.'' Only choice D describes something the engineers did; every other choice makes the engineers themselves the thing corroded, a dangling modifier.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('ff0966da-0c50-5ca6-adc1-e66af79f24ca', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 21, 'standard_conventions', 'boundaries', 'hard', 'mc', 'Three ingredients — teff flour, water, and a starter saved from the previous _______ are all that traditional injera requires.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"batch,"},{"key":"B","text":"batch"},{"key":"C","text":"batch;"},{"key":"D","text":"batch —"}]'::jsonb, 'D', null, 'The list opened with a dash, so it must close with a dash before the sentence resumes at ''are.'' Choice A mixes a dash with a comma, the most common pair error on the test, and choice B never closes the interruption at all.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('8a02fbbd-e437-5c75-ab2f-26130318a8ee', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 22, 'standard_conventions', 'form_structure_sense', 'hard', 'mc', 'The park''s guidebook advises visitors to arrive early, to carry at least two liters of water, and _______ the marked trails even when a shortcut looks obvious.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"staying on"},{"key":"B","text":"that they stay on"},{"key":"C","text":"to stay on"},{"key":"D","text":"they should stay on"}]'::jsonb, 'C', null, 'The list already has two items in the same form, ''to arrive'' and ''to carry,'' so the third must match: ''to stay.'' Choice A breaks the parallel with an -ing form, and choices B and D jam a new clause where a matching phrase belongs.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('2a69f606-a825-5aa6-adb0-595d1624a8d5', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 23, 'expression_ideas', 'transitions', 'easy', 'mc', 'A lichen looks like a single organism, but each one is a partnership between a fungus and an alga or a cyanobacterium, with the fungus providing shelter and the alga providing food. _______ a lichen can colonize bare rock where neither partner could survive on its own.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"For example,"},{"key":"B","text":"As a result,"},{"key":"C","text":"In contrast,"},{"key":"D","text":"Similarly,"}]'::jsonb, 'B', null, 'Living on bare rock is a consequence of the partnership described in the first sentence, so the transition must signal a result. ''For example'' is the trap: the second sentence is not an instance of a partnership but an outcome of it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('f3038977-70e6-5fdd-a694-a95b48f27a55', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 24, 'expression_ideas', 'transitions', 'medium', 'mc', 'Early electric cars of the 1900s were quiet, clean, and easy to start, and for a few years they outsold gasoline models in several American cities. _______ their short range and the spread of cheap gasoline soon pushed them out of the market.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"However,"},{"key":"B","text":"Therefore,"},{"key":"C","text":"In addition,"},{"key":"D","text":"Likewise,"}]'::jsonb, 'A', null, 'The first sentence lists advantages and early success; the second reports failure, so the relationship is contrast. ''Therefore'' is the trap: being pushed out of the market is not a result of being quiet and clean.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('496a8e0e-f898-570a-a65c-86881712fec5', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 25, 'expression_ideas', 'rhetorical_synthesis', 'medium', 'mc', 'While researching a topic, a student has taken the following notes:
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('df205cc1-4f18-5439-a2c6-0d02ff6c7372', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 26, 'expression_ideas', 'transitions', 'hard', 'mc', 'The restorers had assumed that the painting''s dark varnish was original. Chemical analysis showed that it had been applied two centuries after the artist''s death; _______ removing it would not be altering the artist''s work but recovering it.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"in other words,"},{"key":"B","text":"nevertheless,"},{"key":"C","text":"for instance,"},{"key":"D","text":"meanwhile,"}]'::jsonb, 'A', null, 'The final clause restates what the analysis means in practice, so it needs a transition that signals restatement. ''Nevertheless'' would set the clause against the analysis, when it actually follows from it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('12eee0b6-8008-5883-aceb-e13df533bfcb', 'bcb26d09-2d4d-5cb7-af6e-c3cd3dbb9acc', 27, 'expression_ideas', 'rhetorical_synthesis', 'hard', 'mc', 'While researching a topic, a student has taken the following notes:
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('8d8d385a-cdd5-5541-a3fa-b9b243408876', 'b0cdfd99-f9e4-5eee-a7cb-b447f51d0592', 2, 'Reading and Writing — Module 2', 'rw', 1920) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('8da175d0-30c1-505b-a864-64645fa04ead', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 1, 'craft_structure', 'words_in_context', 'easy', 'mc', 'Tardigrades, microscopic animals found in moss and pond sediment, are famously _______: individuals have survived being frozen, heated past the boiling point of water, and exposed to the vacuum of space.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"elusive"},{"key":"B","text":"resilient"},{"key":"C","text":"abundant"},{"key":"D","text":"docile"}]'::jsonb, 'B', null, 'The colon lists extreme conditions the animals survived, so the blank must mean able to withstand hardship: resilient. ''Abundant'' is the trap for a reader who seizes on ''found in moss and pond sediment,'' but the list is about survival, not numbers.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('53634274-b6db-5fae-a718-03ea233b7c81', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 2, 'craft_structure', 'words_in_context', 'medium', 'mc', 'The treaty''s central clause was so _______ that both governments announced the agreement as a victory, each reading the wording in its own favor and each sincerely believing the other had conceded.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"ambiguous"},{"key":"B","text":"rigid"},{"key":"C","text":"explicit"},{"key":"D","text":"provisional"}]'::jsonb, 'A', null, 'A clause that two sides can read in opposite ways is ambiguous. ''Explicit'' states the opposite of what the sentence describes, and ''provisional'' (temporary) has nothing to do with how the wording was interpreted.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('13c153e1-85a3-51a3-a2cd-62c0a9b25a7f', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 3, 'craft_structure', 'words_in_context', 'medium', 'mc', 'Ibn Battuta''s account of his fourteenth-century travels across Africa and Asia is _______ in places, since he describes a few cities he almost certainly never visited, yet it remains an irreplaceable record of the Islamic world of his day.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"exhaustive"},{"key":"B","text":"concise"},{"key":"C","text":"impartial"},{"key":"D","text":"unreliable"}]'::jsonb, 'D', null, 'Describing cities he never saw makes parts of the account untrustworthy, and ''yet it remains irreplaceable'' confirms the blank is a flaw being conceded. ''Exhaustive'' would be praise, which clashes with ''yet.''') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('a437ea9b-ada9-5159-ae64-d42fc7f53fbb', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 4, 'craft_structure', 'text_structure_purpose', 'medium', 'mc', 'Sourdough starters are often said to belong to their city, as if a San Francisco loaf could not be made anywhere else. A 2020 study that sent identical flour and instructions to professional bakers on four continents found that the resulting starters did vary, but that the variation tracked the microbes on the bakers'' hands and in their kitchens, not their location on the map. The terroir of sourdough, it seems, is personal rather than regional.', 'Which choice best describes the function of the second sentence in the text as a whole?', '[{"key":"A","text":"It provides evidence that supports the popular belief described in the first sentence."},{"key":"B","text":"It defines the term ''terroir'' as it is used in the third sentence."},{"key":"C","text":"It presents research findings that undercut the popular belief described in the first sentence."},{"key":"D","text":"It describes the steps required to make a sourdough starter at home."}]'::jsonb, 'C', null, 'The first sentence states a belief (starters belong to a city); the second reports a study showing location did not matter. Choice A reverses the relationship, a trap for a reader who notices that the starters ''did vary'' without reading what the variation tracked.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('457e25ba-b2f7-5416-a217-3c47454de977', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 5, 'craft_structure', 'words_in_context', 'hard', 'mc', 'The composer''s late quartets were received coolly at their premieres, and even sympathetic critics found them _______; only a generation later did audiences begin to hear their strangeness as depth rather than confusion.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"sentimental"},{"key":"B","text":"derivative"},{"key":"C","text":"impenetrable"},{"key":"D","text":"conventional"}]'::jsonb, 'C', null, 'The clue is ''strangeness'' first heard as ''confusion,'' so early listeners found the works impossible to understand: impenetrable. ''Conventional'' and ''derivative'' describe music that is too familiar, the opposite of strange.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('38f642cb-cb14-58a0-ab7f-b7c67b19c966', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 6, 'craft_structure', 'words_in_context', 'hard', 'mc', 'Rather than _______ the rival theory, the paper simply ignores it, which several reviewers found more troubling than an open disagreement would have been.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"key":"A","text":"endorsing"},{"key":"B","text":"refuting"},{"key":"C","text":"anticipating"},{"key":"D","text":"publicizing"}]'::jsonb, 'B', null, 'The reviewers wanted ''an open disagreement'' instead of silence, so the thing the paper failed to do is argue against the rival theory: refute it. ''Endorsing'' is the trap set by ''rather than,'' but endorsing a rival would not be a disagreement at all.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('1e0703a1-1f84-5950-a986-04e1d97e357b', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 7, 'craft_structure', 'text_structure_purpose', 'hard', 'mc', 'She had learned the river the way one learns a language: first its nouns, the sandbar, the sunken barge, the eddy below the mill, and only later its grammar, the way a rise upstream would rearrange every one of them by morning. Visitors asked her how deep it was. She never knew how to answer. Deep where, she wanted to say. Deep when.', 'Which choice best states the main purpose of the text?', '[{"key":"A","text":"To warn visitors about the hidden hazards of the river"},{"key":"B","text":"To criticize visitors for asking questions they could answer themselves"},{"key":"C","text":"To describe the geography of the river in precise detail"},{"key":"D","text":"To convey that the narrator''s knowledge of the river is intimate and ever-changing in a way a simple question cannot capture"}]'::jsonb, 'D', null, 'The language comparison shows her knowledge as layered and alive, and ''Deep where... Deep when'' shows why a single number cannot hold it. Choice B is the trap: she is not scornful of the visitors, only unable to compress what she knows into their question.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('5afeacce-e28c-55ad-a09f-1fce16c919c8', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 8, 'craft_structure', 'text_structure_purpose', 'hard', 'mc', 'Supporters of a four-day school week point to lower costs and better teacher retention. Skeptics reply that the savings are small, since buildings still need heating, and that working parents must find childcare for the fifth day. The best evidence so far comes from rural districts, where the shorter week has coincided with modest gains in attendance but no measurable change in test scores. The debate remains unsettled, in other words, because the policy''s costs and benefits fall on different people.', 'Which choice best describes the overall structure of the text?', '[{"key":"A","text":"Two opposing positions are summarized, the available evidence is weighed, and a reason the disagreement persists is offered."},{"key":"B","text":"A policy is proposed, and the reasons for rejecting it are listed."},{"key":"C","text":"The author argues for one side of a debate and then concedes a point to the other side."},{"key":"D","text":"A prediction about a policy is made and then confirmed by data from rural districts."}]'::jsonb, 'A', null, 'Supporters, then skeptics, then the evidence, then a diagnosis of why no one is convinced: that is choice A step by step. Choice C is the trap; the author summarizes both sides without taking either.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('d2eb6cd9-ba2f-5658-ad61-1a3cac52b921', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 9, 'information_ideas', 'evidence_textual', 'easy', 'mc', 'Archaeologists excavating a Bronze Age settlement found a clay loom weight in nearly every house, although no finished textiles survived in the soil. They hypothesize that the settlement produced cloth for exchange with neighboring communities rather than for household use alone.', 'Which finding, if true, would most directly support the archaeologists'' hypothesis?', '[{"key":"A","text":"The number of loom weights in each house far exceeds what a single family would need to clothe itself."},{"key":"B","text":"Textiles decay quickly in the region''s damp soil."},{"key":"C","text":"The houses in the settlement were built of mud brick."},{"key":"D","text":"The loom weights are similar in shape to those found at other sites in the region."}]'::jsonb, 'A', null, 'Weaving capacity well beyond a household''s own needs points to production for others, which is the hypothesis. Choice B is the trap: it explains why no cloth survived, but says nothing about who the cloth was made for.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('01ee6a88-dd02-5467-a6f0-42504f66d6b8', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 10, 'information_ideas', 'inferences', 'easy', 'mc', 'In the 1990s a city planted thousands of street trees of a single fast-growing species, chosen for its uniform look. When a beetle that attacks only that species arrived two decades later, the city lost nearly half its tree canopy within five years. Planners in other cities have drawn a clear lesson from the episode: _______', 'Which choice most logically completes the text?', '[{"key":"A","text":"fast-growing trees should never be planted along city streets."},{"key":"B","text":"beetles are the greatest threat facing urban trees."},{"key":"C","text":"trees planted in the 1990s are now too old to be useful."},{"key":"D","text":"a street canopy made up of many species is far less likely to be devastated by any single pest."}]'::jsonb, 'D', null, 'The disaster followed from planting one species, so the lesson is diversity. Choice A is the trap: the problem was uniformity, not growth speed, which the passage mentions only as the reason the species was chosen.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('e38d6a75-8f40-5ad0-a593-58de50114732', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 11, 'information_ideas', 'central_ideas_details', 'medium', 'mc', 'A Venus flytrap does not close on the first touch. Tiny hairs inside the trap must be bent twice within about twenty seconds before the lobes snap shut, and the plant does not begin producing digestive enzymes until the struggling insect has triggered the hairs several more times. This counting keeps the plant from wasting energy on raindrops or windblown debris, a crude but effective way of telling food from false alarms.', 'Which choice best states the main idea of the text?', '[{"key":"A","text":"The Venus flytrap closes faster than any other carnivorous plant."},{"key":"B","text":"Insects can escape a Venus flytrap if they stop moving after the trap closes."},{"key":"C","text":"The Venus flytrap''s need for repeated triggering prevents it from closing on things that are not prey."},{"key":"D","text":"The Venus flytrap produces digestive enzymes continuously."}]'::jsonb, 'C', null, 'The passage explains the counting mechanism and then states its purpose in the last sentence, which choice C restates. Choice B is a tempting inference, but the text never says what happens to an insect that stays still, so it cannot be the main idea.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('a1445ff2-b038-5ae3-a8f1-283e80cdf484', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 12, 'information_ideas', 'central_ideas_details', 'hard', 'mc', 'Every spring my father repainted the boat the same blue, and every spring he claimed it was a slightly different shade, truer, he said, closer to what the boat was supposed to be. I could never see the difference. It was years before I understood that the painting was not about the color at all, and that a person may spend a lifetime perfecting something precisely so that it can never be finished.', 'Which choice best states the main idea of the text?', '[{"key":"A","text":"The narrator doubted the father''s ability to tell one shade of blue from another."},{"key":"B","text":"The narrator came to see the father''s annual repainting as a ritual whose value lay in the act itself, not in the result."},{"key":"C","text":"The boat required repainting every year to protect it from the weather."},{"key":"D","text":"The narrator regrets never having learned to paint the boat."}]'::jsonb, 'B', null, 'The final sentence delivers the realization: the painting ''was not about the color at all'' but about an activity kept deliberately unfinished. Choice A is a detail from the middle of the passage that the ending reinterprets, not the main idea.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('e64c4f19-5da3-5378-ae70-0f1f7b4bbc38', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 13, 'information_ideas', 'evidence_textual', 'hard', 'mc', 'Linguists have proposed that a cluster of rare words shared by two unrelated languages spoken on opposite sides of a mountain range is evidence of direct trade contact between the two peoples in the distant past.', 'Which finding, if true, would most directly weaken the linguists'' proposal?', '[{"key":"A","text":"The two languages have very different grammatical structures."},{"key":"B","text":"Both languages are still spoken by sizable communities today."},{"key":"C","text":"Historical records show that a third language, spoken by merchants who crossed the range, contained all of the shared words."},{"key":"D","text":"The mountain range has several passes that remain open throughout the year."}]'::jsonb, 'C', null, 'If a merchant language carried the words to both sides, the two peoples need never have met, so the evidence for direct contact collapses. Choice D is the trap: open passes make direct contact easier, which would support the proposal rather than weaken it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('e69c2ac2-c769-53a7-ab28-75265ea4adc0', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 14, 'information_ideas', 'evidence_quantitative', 'hard', 'mc', 'A city compared ridership on two of its bus routes.
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('b802fce8-a0eb-5b92-a083-8e534d25fa5e', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 15, 'information_ideas', 'inferences', 'hard', 'mc', 'In many languages the words for ''two'' and ''three'' are far older than the words for larger numbers, and such small-number words are rarely replaced over the centuries. Linguists who reconstruct ancient vocabularies therefore treat them as unusually stable anchors. When two languages have strikingly different words for ''two,'' then, _______', 'Which choice most logically completes the text?', '[{"key":"A","text":"the two languages must have borrowed their number words from a third language."},{"key":"B","text":"the two languages are probably either unrelated or separated by a very long period of divergence."},{"key":"C","text":"the speakers of both languages most likely used a counting system based on ten."},{"key":"D","text":"the two languages will also differ in their words for ''three.''"}]'::jsonb, 'B', null, 'If a word almost never changes, two languages that differ in it have either never shared it or have been apart long enough for a rare change to occur. Choice D is the trap: stability of one word does not guarantee anything about another word.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('af9d4019-5d28-576c-a420-d97094d8b0f9', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 16, 'standard_conventions', 'boundaries', 'medium', 'mc', 'The mill''s original waterwheel was moved to a museum in _______ the millstones still grind flour for the village bakery every Saturday.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"1987. However,"},{"key":"B","text":"1987, however,"},{"key":"C","text":"1987 however,"},{"key":"D","text":"1987, however"}]'::jsonb, 'A', null, 'Both halves are complete sentences, and ''however'' belongs to the second, so the second must start fresh after a period. ''However'' never has the power to join two sentences on its own, which makes every comma-based choice a splice or a run-on.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('8c9a6f09-12c4-5252-a195-e8785f4fdc00', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 17, 'standard_conventions', 'boundaries', 'medium', 'mc', 'The main threat to the reef is not tourism _______ warming water, which bleaches the coral by driving out the algae it depends on.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"but:"},{"key":"B","text":"but;"},{"key":"C","text":"but,"},{"key":"D","text":"but"}]'::jsonb, 'D', null, '''Not tourism but warming water'' is a single contrast inside one clause, and no punctuation belongs between ''but'' and the noun it introduces. The colon and semicolon in choices A and B both require a complete sentence before them, which ''The main threat is not tourism but'' is not.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('972b2e95-5d3e-5dd9-acce-77dba7ed997f', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 18, 'standard_conventions', 'form_structure_sense', 'medium', 'mc', 'The variety of dialects spoken along the river''s four hundred miles _______ linguists for more than a century.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"have intrigued"},{"key":"B","text":"intrigue"},{"key":"C","text":"has intrigued"},{"key":"D","text":"are intriguing"}]'::jsonb, 'C', null, 'Cross out the prepositional phrases and the subject is ''The variety,'' which is singular: ''has intrigued.'' ''Dialects'' and ''miles'' sit next to the blank to pull the ear toward a plural verb.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('dc1af4de-b784-5c7d-a130-c09f2096a461', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 19, 'standard_conventions', 'form_structure_sense', 'medium', 'mc', 'When a bank and a credit union merge, _______ customers usually keep their original account numbers for at least a year.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"its"},{"key":"B","text":"their"},{"key":"C","text":"it''s"},{"key":"D","text":"there"}]'::jsonb, 'B', null, 'The customers belong to two institutions, ''a bank and a credit union,'' a plural antecedent, so the pronoun is ''their.'' ''Its'' is the trap for a reader who hears ''merge'' and imagines a single resulting company, but the sentence names two.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('ddc576f7-4030-5bfb-a257-d54494f2f918', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 20, 'standard_conventions', 'boundaries', 'hard', 'mc', 'The violinist, whose recordings from the 1950s are still in _______ never performed in public after the age of forty.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"print,"},{"key":"B","text":"print"},{"key":"C","text":"print;"},{"key":"D","text":"print —"}]'::jsonb, 'A', null, 'The clause ''whose recordings from the 1950s are still in print'' is a non-essential aside that opened with a comma after ''violinist,'' so it must close with a comma before the verb ''performed.'' The dash in choice D mixes fence types, and choice B never closes the aside.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('a47fe0c4-8882-56f1-a4a4-b7326a172b0b', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 21, 'standard_conventions', 'boundaries', 'hard', 'mc', 'The museum''s three largest gifts came from a shipping family in Mumbai, _______ a retired schoolteacher in Lagos, Nigeria; and an anonymous donor who gave through a lawyer.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"India,"},{"key":"B","text":"India:"},{"key":"C","text":"India"},{"key":"D","text":"India;"}]'::jsonb, 'D', null, 'Because the list items contain commas of their own (''Mumbai, India''), the items must be separated by semicolons, and the ''; and'' before the last item confirms it. A comma at the blank would blur where the first donor ends and the second begins.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('236f5e7b-4ecf-5331-a110-d0f3ab6fae0a', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 22, 'standard_conventions', 'form_structure_sense', 'hard', 'mc', 'Astronomers announced that the comet, which last passed close to Earth in 1986, _______ again in 2061.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"key":"A","text":"will return"},{"key":"B","text":"returned"},{"key":"C","text":"has returned"},{"key":"D","text":"would have returned"}]'::jsonb, 'A', null, 'The time cue ''2061'' places the return in the future, so the verb is ''will return.'' Choice B is the trap for a reader whose ear locks onto ''announced'' and ''1986,'' both past, but the blank describes a different event with its own date.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('f36a288a-6d63-5ce7-a520-919590d4c7c1', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 23, 'expression_ideas', 'transitions', 'easy', 'mc', 'Recycling glass saves energy, since crushed glass melts at a lower temperature than the raw sand it replaces. _______ many cities have stopped collecting it, because the crushed glass is heavy to haul and sells for very little.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"Consequently,"},{"key":"B","text":"Even so,"},{"key":"C","text":"For example,"},{"key":"D","text":"Similarly,"}]'::jsonb, 'B', null, 'The first sentence gives a reason to recycle glass; the second says cities have stopped anyway, which is a concession. ''Consequently'' is the trap: saving energy is not the reason cities stopped collecting.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('2e675aad-6424-53bc-a352-70ed62bd806d', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 24, 'expression_ideas', 'rhetorical_synthesis', 'medium', 'mc', 'While researching a topic, a student has taken the following notes:
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('53a05420-c141-5f74-a330-7593cb541cf1', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 25, 'expression_ideas', 'rhetorical_synthesis', 'medium', 'mc', 'While researching a topic, a student has taken the following notes:
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('f8f2dfdc-ee9d-5e1a-a933-7046e57cc00c', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 26, 'expression_ideas', 'transitions', 'hard', 'mc', 'The Dutch tulip craze of the 1630s is routinely cited as the first speculative bubble, complete with fortunes lost overnight. _______ historians who have examined the surviving contracts find that most trades were never settled, and that the famous ruin of thousands of investors is largely a later invention.', 'Which choice completes the text with the most logical transition?', '[{"key":"A","text":"Thus"},{"key":"B","text":"Indeed"},{"key":"C","text":"Yet"},{"key":"D","text":"Likewise"}]'::jsonb, 'C', null, 'The second sentence contradicts the familiar story in the first, so the transition must signal contrast. ''Indeed'' is the trap: it would promise confirmation of the fortunes-lost story, when the historians are dismantling it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('db5fda83-c9e6-5ce3-a653-06d936399d81', '8d8d385a-cdd5-5541-a3fa-b9b243408876', 27, 'expression_ideas', 'rhetorical_synthesis', 'hard', 'mc', 'While researching a topic, a student has taken the following notes:
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('f778136b-e363-5c68-a030-99c0efcac176', 'b0cdfd99-f9e4-5eee-a7cb-b447f51d0592', 3, 'Math — Module 1', 'math', 2100) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('44c94f51-7494-57bb-aa12-254ea9633298', 'f778136b-e363-5c68-a030-99c0efcac176', 1, 'algebra', 'linear_eq_one_var', 'easy', 'mc', null, 'If 3(x − 4) = 2x + 5, what is the value of x?', '[{"key":"A","text":"9"},{"key":"B","text":"1"},{"key":"C","text":"17"},{"key":"D","text":"−7"}]'::jsonb, 'C', null, 'Distribute: 3x − 12 = 2x + 5, then subtract 2x and add 12 to get x = 17. Choice A comes from forgetting to multiply the −4 by 3, and choice D from moving the −12 without changing its sign.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('d3d945f1-3993-5638-a790-3793577d228a', 'f778136b-e363-5c68-a030-99c0efcac176', 2, 'algebra', 'linear_eq_two_var', 'easy', 'spr', null, 'The line y = −2x + 9 passes through the point (k, 1). What is the value of k?', null, '4', '["4.0"]'::jsonb, 'Substitute y = 1: 1 = −2k + 9, so 2k = 8 and k = 4. Substituting the 1 for x instead of y is the common slip and gives 7.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('0d25e3f0-d0ee-56d6-ad8a-d879add389a5', 'f778136b-e363-5c68-a030-99c0efcac176', 3, 'algebra', 'linear_functions', 'easy', 'mc', null, 'A phone plan costs $12 per month plus $0.05 for each text message sent. Which function gives the monthly cost C, in dollars, for t text messages?', '[{"key":"A","text":"C(t) = 12t + 0.05"},{"key":"B","text":"C(t) = 0.05t + 12"},{"key":"C","text":"C(t) = 12.05t"},{"key":"D","text":"C(t) = 0.05(t + 12)"}]'::jsonb, 'B', null, 'The fixed $12 does not change with t and the $0.05 is multiplied by the number of messages, giving 0.05t + 12. Choice A swaps the roles: it would charge $12 per message.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('11cf8b20-00c8-51b6-a25b-a3c08155a1ee', 'f778136b-e363-5c68-a030-99c0efcac176', 4, 'advanced_math', 'equivalent_expressions', 'easy', 'mc', null, 'Which expression is equivalent to (2x + 3)(x − 5)?', '[{"key":"A","text":"2x² + 7x − 15"},{"key":"B","text":"2x² − 13x − 15"},{"key":"C","text":"2x² − 2x − 15"},{"key":"D","text":"2x² − 7x − 15"}]'::jsonb, 'D', null, 'Multiply each term: 2x² − 10x + 3x − 15 = 2x² − 7x − 15. Choice B comes from writing −10x − 3x instead of −10x + 3x.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('b6bba27e-5631-5866-a58f-07c06a300230', 'f778136b-e363-5c68-a030-99c0efcac176', 5, 'advanced_math', 'nonlinear_functions', 'easy', 'mc', null, 'The function f is defined by f(x) = x² − 4x + 1. What is the value of f(−2)?', '[{"key":"A","text":"−3"},{"key":"B","text":"5"},{"key":"C","text":"13"},{"key":"D","text":"−11"}]'::jsonb, 'C', null, 'f(−2) = (−2)² − 4(−2) + 1 = 4 + 8 + 1 = 13. Choice B results from treating (−2)² as −4, and choice A from treating −4(−2) as −8.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('e47dde9e-073e-52bc-a1ab-b415ebd905b3', 'f778136b-e363-5c68-a030-99c0efcac176', 6, 'psda', 'percentages', 'easy', 'mc', null, 'A store sets the retail price of each item at 60% above its wholesale cost. A lamp has a wholesale cost of $45. What is its retail price?', '[{"key":"A","text":"$27"},{"key":"B","text":"$72"},{"key":"C","text":"$105"},{"key":"D","text":"$75"}]'::jsonb, 'B', null, '60% of 45 is 27, and the retail price is 45 + 27 = $72, or 1.6 × 45 directly. Choice A is the markup alone, not the price.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('692c3ee8-4be5-5b44-a2b9-008c74cb781d', 'f778136b-e363-5c68-a030-99c0efcac176', 7, 'geometry_trig', 'area_volume', 'easy', 'mc', null, 'A rectangular tank is 40 centimeters long, 25 centimeters wide, and 30 centimeters tall. Water fills the tank to a depth of 18 centimeters. What is the volume of the water, in cubic centimeters?', '[{"key":"A","text":"18,000"},{"key":"B","text":"30,000"},{"key":"C","text":"12,000"},{"key":"D","text":"1,800"}]'::jsonb, 'A', null, 'The water forms a box 40 by 25 by 18, so its volume is 40 × 25 × 18 = 18,000. Choice B uses the full height of 30 instead of the water''s depth.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('6e358e24-f375-5d4f-afba-1b3909c17543', 'f778136b-e363-5c68-a030-99c0efcac176', 8, 'geometry_trig', 'lines_angles_triangles', 'easy', 'mc', null, 'In triangle ABC, the measure of angle A is 30°, and the measure of angle B is twice the measure of angle C. What is the measure of angle B?', '[{"key":"A","text":"50°"},{"key":"B","text":"75°"},{"key":"C","text":"120°"},{"key":"D","text":"100°"}]'::jsonb, 'D', null, 'Angles B and C share the remaining 150°, and B = 2C, so 3C = 150 and C = 50°, making B = 100°. Choice A is angle C, the other unknown.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('f305ea56-385d-5c5b-ace3-e6c465248a1d', 'f778136b-e363-5c68-a030-99c0efcac176', 9, 'algebra', 'systems_two_linear', 'medium', 'mc', null, 'Tickets to a school play cost $8 for students and $14 for adults. One evening, 150 tickets were sold for a total of $1,620. How many adult tickets were sold?', '[{"key":"A","text":"80"},{"key":"B","text":"60"},{"key":"C","text":"75"},{"key":"D","text":"70"}]'::jsonb, 'D', null, 'With s + a = 150 and 8s + 14a = 1,620, substitute s = 150 − a: 1,200 + 6a = 1,620, so a = 70. Choice A is the number of student tickets, the other unknown; the question asks for adults.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('03064c68-0216-572b-a3e1-6bed1255578a', 'f778136b-e363-5c68-a030-99c0efcac176', 10, 'algebra', 'linear_functions', 'medium', 'mc', null, 'The function h(t) = 1,200 − 45t models the height, in meters, of a hot-air balloon t minutes after it begins to descend. Which of the following is the best interpretation of 45 in this context?', '[{"key":"A","text":"The balloon begins its descent at a height of 45 meters."},{"key":"B","text":"The balloon reaches the ground after 45 minutes."},{"key":"C","text":"The balloon descends 45 meters each minute."},{"key":"D","text":"The balloon descends a total of 45 meters."}]'::jsonb, 'C', null, 'In a linear model the number multiplied by t is the rate of change per unit of t, so 45 is meters per minute. The starting height is 1,200 (choice A), and the landing time is 1,200 ÷ 45, about 26.7 minutes, not 45 (choice B).') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('07dcfcaf-e2ac-5995-a4ea-09602e72cefa', 'f778136b-e363-5c68-a030-99c0efcac176', 11, 'advanced_math', 'nonlinear_eq_systems', 'medium', 'spr', null, 'What is the positive solution to the equation x² − 5x − 24 = 0?', null, '8', '["8.0"]'::jsonb, 'Factor into (x − 8)(x + 3) = 0, so x = 8 or x = −3, and the positive solution is 8. Reversing the signs to (x + 8)(x − 3) gives the wrong pair.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('c9b0c697-fe8d-5148-a535-55cdbb1949f5', 'f778136b-e363-5c68-a030-99c0efcac176', 12, 'advanced_math', 'equivalent_expressions', 'medium', 'mc', null, 'For positive values of x and y, which expression is equivalent to (x⁶y³)^(1/3)?', '[{"key":"A","text":"x²y"},{"key":"B","text":"x¹⁸y⁹"},{"key":"C","text":"x³y"},{"key":"D","text":"x^(1/2)y"}]'::jsonb, 'A', null, 'A power of a product applies to each factor, and exponents multiply: x^(6 × 1/3) · y^(3 × 1/3) = x²y. Choice B multiplies by 3 instead of by 1/3.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('8f846c4a-5025-599f-abc8-ab626c0fe3ed', 'f778136b-e363-5c68-a030-99c0efcac176', 13, 'advanced_math', 'nonlinear_functions', 'medium', 'mc', null, 'The function g is defined by g(x) = 2x² − 12x + 5. What is the minimum value of g(x)?', '[{"key":"A","text":"5"},{"key":"B","text":"3"},{"key":"C","text":"−13"},{"key":"D","text":"−31"}]'::jsonb, 'C', null, 'The vertex is at x = −b/(2a) = 12/4 = 3, and g(3) = 18 − 36 + 5 = −13. Choice B is the x-coordinate of the vertex, not the minimum value, and choice A is g(0).') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('07b4f9ea-3ded-58f1-ad82-e10277dc04b8', 'f778136b-e363-5c68-a030-99c0efcac176', 14, 'advanced_math', 'nonlinear_functions', 'medium', 'mc', null, 'A bacteria population starts at 500 and doubles every 3 hours. Which equation gives the population P after t hours?', '[{"key":"A","text":"P = 500(2)^(t/3)"},{"key":"B","text":"P = 500(2)^(3t)"},{"key":"C","text":"P = 500(3)^(t/2)"},{"key":"D","text":"P = 500 + 2^(t/3)"}]'::jsonb, 'A', null, 'Doubling every 3 hours means the number of doublings after t hours is t/3, so P = 500 · 2^(t/3). Choice B would double the population three times every hour.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('ae6c7dcb-5900-563b-a7ba-a5292cb0197b', 'f778136b-e363-5c68-a030-99c0efcac176', 15, 'psda', 'probability', 'medium', 'mc', null, 'A bag contains only red and blue marbles. The probability of drawing a red marble at random is 3/8. If there are 15 red marbles, how many blue marbles are in the bag?', '[{"key":"A","text":"24"},{"key":"B","text":"25"},{"key":"C","text":"40"},{"key":"D","text":"9"}]'::jsonb, 'B', null, 'If 15 red marbles are 3/8 of the bag, the bag holds 15 ÷ (3/8) = 40 marbles, so 40 − 15 = 25 are blue. Choice C is the total, not the number of blue marbles.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('4c6aff76-4c51-56cc-aaef-5baf6601a367', 'f778136b-e363-5c68-a030-99c0efcac176', 16, 'algebra', 'linear_inequalities', 'hard', 'spr', null, 'A worker earns $15 per hour for the first 40 hours worked in a week and $22.50 per hour for each hour beyond 40. What is the minimum number of whole hours the worker must work in one week to earn at least $825?', null, '50', '["50.0"]'::jsonb, 'The first 40 hours earn 40 × 15 = $600, leaving $225 to earn at $22.50 per hour: 225 ÷ 22.5 = 10 more hours, so 50 hours in total. Answering 10 forgets to add the first 40 hours back.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('287f0167-23d6-5e59-a516-6bd4a5fb2700', 'f778136b-e363-5c68-a030-99c0efcac176', 17, 'algebra', 'systems_two_linear', 'hard', 'mc', null, 'The system of equations 6x − 4y = 10 and 9x + ky = 15 has infinitely many solutions. What is the value of k?', '[{"key":"A","text":"6"},{"key":"B","text":"−9"},{"key":"C","text":"−6"},{"key":"D","text":"4"}]'::jsonb, 'C', null, 'Infinitely many solutions means the equations describe the same line, so the second must be a multiple of the first: 9 is 1.5 × 6 and 15 is 1.5 × 10, so k = 1.5 × (−4) = −6. Choice A drops the sign of the −4.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('120aef43-9aa0-519b-a341-614a701e03b4', 'f778136b-e363-5c68-a030-99c0efcac176', 18, 'algebra', 'linear_eq_two_var', 'hard', 'spr', null, 'Line ℓ is perpendicular to the line 2x + 5y = 20 and passes through the point (4, −1). What is the y-coordinate of the y-intercept of line ℓ?', null, '-11', '["-11.0"]'::jsonb, 'Rewrite the given line as y = −(2/5)x + 4; a perpendicular line has the negative reciprocal slope, 5/2. Through (4, −1): −1 = (5/2)(4) + b, so b = −1 − 10 = −11. Using the slope −2/5 or 2/5 instead of 5/2 is the usual error.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('ddb0c6db-1c4b-59db-a4a1-c2cc8ec404fe', 'f778136b-e363-5c68-a030-99c0efcac176', 19, 'advanced_math', 'nonlinear_eq_systems', 'hard', 'spr', null, 'The system y = x² − 2x and y = 2x − 3 has two solutions. What is the sum of the x-coordinates of the two solutions?', null, '4', '["4.0"]'::jsonb, 'Set the expressions equal: x² − 2x = 2x − 3, so x² − 4x + 3 = 0, which factors as (x − 1)(x − 3). The x-coordinates are 1 and 3, with sum 4. Reporting a y-coordinate or just one solution is the common slip.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('a581d713-80e8-5ef4-a669-a265519a4c06', 'f778136b-e363-5c68-a030-99c0efcac176', 20, 'advanced_math', 'equivalent_expressions', 'hard', 'mc', null, 'For x ≠ 2 and x ≠ −3, which expression is equivalent to (x² − 9) / (x² + x − 6)?', '[{"key":"A","text":"(x − 3) / (x − 2)"},{"key":"B","text":"(x + 3) / (x − 2)"},{"key":"C","text":"(x − 3) / (x + 3)"},{"key":"D","text":"(x + 3) / (x + 2)"}]'::jsonb, 'A', null, 'Factor both: (x − 3)(x + 3) over (x + 3)(x − 2); the (x + 3) cancels, leaving (x − 3)/(x − 2). Choice B keeps the factor that cancels and drops the one that stays.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('832a343c-4d0d-5347-a645-69af6765fdaf', 'f778136b-e363-5c68-a030-99c0efcac176', 21, 'psda', 'one_var_data', 'hard', 'mc', null, 'The ages of the 7 members of a chess club are 12, 13, 13, 14, 15, 17, and 21. If the 21-year-old leaves the club, which statistic for the remaining members changes by the greatest amount?', '[{"key":"A","text":"Range"},{"key":"B","text":"Mean"},{"key":"C","text":"Median"},{"key":"D","text":"Mode"}]'::jsonb, 'A', null, 'The range falls from 21 − 12 = 9 to 17 − 12 = 5, a change of 4. The mean drops from 15 to 14 (a change of 1), the median from 14 to 13.5, and the mode stays 13. Removing an extreme value always hits the range hardest.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('d84ec14c-7c67-58db-add1-43ac0e4d8929', 'f778136b-e363-5c68-a030-99c0efcac176', 22, 'geometry_trig', 'right_triangles_trig', 'hard', 'spr', null, 'In right triangle PQR, angle Q is the right angle, PQ = 8, and QR = 15. What is the value of sin P?', null, '15/17', '[".8823","0.8823",".8824","0.8824"]'::jsonb, 'The hypotenuse PR is √(8² + 15²) = 17. Sine is opposite over hypotenuse, and the side opposite angle P is QR = 15, so sin P = 15/17. Using the adjacent side gives 8/17, which is cos P.') on conflict (id) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('40c5c5fa-8903-56f6-a97f-1e840fc6db88', 'b0cdfd99-f9e4-5eee-a7cb-b447f51d0592', 4, 'Math — Module 2', 'math', 2100) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('7bd0e4ed-3d12-5a3e-a238-65089f5ff0e5', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 1, 'algebra', 'linear_eq_one_var', 'easy', 'mc', null, 'If x/4 + 7 = 12, what is the value of x?', '[{"key":"A","text":"20"},{"key":"B","text":"76"},{"key":"C","text":"5"},{"key":"D","text":"48"}]'::jsonb, 'A', null, 'Subtract 7 to get x/4 = 5, then multiply by 4: x = 20. Choice B multiplies both 12 and 7 by 4 and adds; choice C stops at x/4 = 5.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('0100d399-19fa-5a5e-ad6c-b2e1bb22e18d', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 2, 'advanced_math', 'nonlinear_functions', 'easy', 'mc', null, 'In the xy-plane, what is the y-intercept of the graph of y = (x − 2)(x + 5)?', '[{"key":"A","text":"(0, 10)"},{"key":"B","text":"(0, −10)"},{"key":"C","text":"(0, 3)"},{"key":"D","text":"(0, −3)"}]'::jsonb, 'B', null, 'Set x = 0: y = (−2)(5) = −10. Choice C adds the constants (−2 + 5) instead of multiplying them.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('46f4f4b8-44e1-540a-a630-51055a603b9b', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 3, 'advanced_math', 'nonlinear_eq_systems', 'easy', 'spr', null, 'If √(2x + 7) = 5, what is the value of x?', null, '9', '["9.0"]'::jsonb, 'Square both sides: 2x + 7 = 25, so 2x = 18 and x = 9. Checking, √(18 + 7) = √25 = 5. Forgetting to square and solving 2x + 7 = 5 gives −1.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('c264ded6-3d5c-5b76-a2f6-7ab85e3d0824', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 4, 'geometry_trig', 'circles', 'easy', 'mc', null, 'In the xy-plane, a circle has the equation (x − 3)² + (y + 2)² = 49. What is the radius of the circle?', '[{"key":"A","text":"49"},{"key":"B","text":"3"},{"key":"C","text":"2"},{"key":"D","text":"7"}]'::jsonb, 'D', null, 'In (x − h)² + (y − k)² = r², the right side is the radius squared, so r = √49 = 7. Choice A forgets to take the square root.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('2597b6e8-368f-5619-a782-5295536456aa', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 5, 'algebra', 'linear_eq_two_var', 'medium', 'mc', null, 'Which equation represents the line that passes through the points (−3, 8) and (1, 0)?', '[{"key":"A","text":"y = −2x + 2"},{"key":"B","text":"y = 2x + 14"},{"key":"C","text":"y = −2x − 2"},{"key":"D","text":"y = −(1/2)x + 1/2"}]'::jsonb, 'A', null, 'The slope is (0 − 8)/(1 − (−3)) = −8/4 = −2, and through (1, 0): 0 = −2(1) + b, so b = 2. Choice C has the right slope but the wrong intercept; check it against (1, 0), where it gives −4.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('5f12543d-7d95-5d86-a761-07a7442df23c', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 6, 'algebra', 'linear_functions', 'medium', 'spr', null, 'The function f is linear, with f(2) = 9 and f(6) = 1. What is the value of f(0)?', null, '13', '["13.0"]'::jsonb, 'The slope is (1 − 9)/(6 − 2) = −2, so moving from x = 2 back to x = 0 adds 2 × 2 = 4 to the output: f(0) = 9 + 4 = 13. Subtracting instead of adding gives 5.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('bd3ad842-70c4-5928-a88b-9fa72bbfcf2e', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 7, 'algebra', 'systems_two_linear', 'medium', 'mc', null, 'If x + 2y = 11 and 3x − y = 5, what is the value of x + y?', '[{"key":"A","text":"3"},{"key":"B","text":"4"},{"key":"C","text":"1"},{"key":"D","text":"7"}]'::jsonb, 'D', null, 'From the second equation y = 3x − 5; substituting gives x + 6x − 10 = 11, so x = 3 and y = 4, and x + y = 7. Choices A and B are x and y alone, but the question asks for their sum.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('1caf6a8a-d48a-538d-ad79-092ea0d8e526', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 8, 'algebra', 'linear_inequalities', 'medium', 'mc', null, 'A bakery can make at most 120 loaves in a day. Each sourdough loaf uses 2 units of flour and each rye loaf uses 3 units, and 300 units of flour are available. If s is the number of sourdough loaves and r is the number of rye loaves, which system of inequalities represents these constraints?', '[{"key":"A","text":"s + r ≥ 120 and 2s + 3r ≤ 300"},{"key":"B","text":"s + r ≤ 120 and 2s + 3r ≤ 300"},{"key":"C","text":"s + r ≤ 120 and 3s + 2r ≤ 300"},{"key":"D","text":"2s + 3r ≤ 120 and s + r ≤ 300"}]'::jsonb, 'B', null, '''At most 120 loaves'' is s + r ≤ 120, and the flour used, 2s + 3r, cannot exceed 300. Choice C swaps the flour amounts, and choice D attaches each limit to the wrong quantity.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('0dbf5972-b669-5173-a090-81b745e323a0', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 9, 'algebra', 'linear_functions', 'medium', 'mc', null, 'The total cost y, in dollars, of renting a hall for x hours is modeled by y = 85x + 240. Which of the following is the best interpretation of 240 in this context?', '[{"key":"A","text":"The cost of each additional hour"},{"key":"B","text":"The fixed fee charged regardless of the number of hours"},{"key":"C","text":"The maximum number of hours the hall can be rented"},{"key":"D","text":"The total cost of renting the hall for one hour"}]'::jsonb, 'B', null, 'When x = 0 the cost is 240, so it is the charge before any hours are counted: a fixed fee. The hourly cost is 85 (choice A), and one hour costs 85 + 240 = 325 (choice D).') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('ae38cf08-e71d-5b8b-a74a-5ebe7f6cf343', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 10, 'advanced_math', 'equivalent_expressions', 'medium', 'mc', null, 'Which expression is equivalent to (3x² − 5x + 2) − (x² − 7x − 4)?', '[{"key":"A","text":"2x² − 12x − 2"},{"key":"B","text":"2x² + 2x − 2"},{"key":"C","text":"4x² − 12x − 2"},{"key":"D","text":"2x² + 2x + 6"}]'::jsonb, 'D', null, 'Subtracting the second polynomial flips every sign in it: 3x² − 5x + 2 − x² + 7x + 4 = 2x² + 2x + 6. Choice A forgets to flip the signs of −7x and −4.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('edccbbb2-9518-57e9-ae82-03b1962c5f60', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 11, 'advanced_math', 'nonlinear_functions', 'medium', 'mc', null, 'The value V, in dollars, of a car t years after it was purchased is modeled by V(t) = 28,000(0.85)^t. By what percent does the car''s value decrease each year?', '[{"key":"A","text":"85%"},{"key":"B","text":"28%"},{"key":"C","text":"15%"},{"key":"D","text":"1.5%"}]'::jsonb, 'C', null, 'Each year the value is multiplied by 0.85, which keeps 85% and removes the other 15%. Choice A is the trap: 85% is what remains, not what is lost.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('8712750f-1ab8-5493-a6f8-dc6781acd5e2', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 12, 'psda', 'percentages', 'medium', 'mc', null, 'After an 18% price increase, a monthly transit pass costs $59. What was the price of the pass before the increase?', '[{"key":"A","text":"$50.00"},{"key":"B","text":"$48.38"},{"key":"C","text":"$41.00"},{"key":"D","text":"$69.62"}]'::jsonb, 'A', null, 'The new price is 118% of the old one, so the old price is 59 ÷ 1.18 = $50. Choice B subtracts 18% of 59 from 59, which undoes the wrong amount; a percent increase is reversed by dividing, not by subtracting.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('f5b1e7eb-061e-5d01-ab57-dcbb45423b75', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 13, 'algebra', 'linear_eq_one_var', 'hard', 'spr', null, 'In the equation 4(x + a) = 4x + 18 − 2a, a is a constant. If the equation has infinitely many solutions, what is the value of a?', null, '3', '["3.0"]'::jsonb, 'Expand: 4x + 4a = 4x + 18 − 2a. The 4x terms match, so the equation is true for every x exactly when 4a = 18 − 2a, giving 6a = 18 and a = 3. Any other a makes the equation false for all x.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('d00a605a-33b6-545a-ade0-5c9624ff98d6', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 14, 'algebra', 'systems_two_linear', 'hard', 'mc', null, 'The system of equations 3x − 2y = 7 and ax + 6y = b, where a and b are constants, has no solution. Which of the following must be true?', '[{"key":"A","text":"a = −9 and b = −21"},{"key":"B","text":"a = 9 and b ≠ 21"},{"key":"C","text":"a = 9 and b = 21"},{"key":"D","text":"a = −9 and b ≠ −21"}]'::jsonb, 'D', null, 'No solution means parallel lines: the same slope but different intercepts. Multiplying the first equation by −3 gives −9x + 6y = −21, so a must be −9, and b must NOT be −21, or the lines would coincide and have infinitely many solutions (choice A).') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('b6260cf1-ff65-5bec-aa02-16b354056a1a', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 15, 'advanced_math', 'equivalent_expressions', 'hard', 'spr', null, 'The expression x² + bx + 36, where b is a negative constant, is equivalent to (x − c)² for some constant c. What is the value of b?', null, '-12', '["-12.0"]'::jsonb, '(x − c)² = x² − 2cx + c², so c² = 36 and c = 6 (taking c positive makes b negative), giving b = −2c = −12. Answering −6 forgets the factor of 2 in the middle term.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('a5bae869-1d63-5034-ac6c-113a2fb97a8c', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 16, 'advanced_math', 'nonlinear_eq_systems', 'hard', 'mc', null, 'How many distinct real solutions does the equation 2x² − 3x + 5 = 0 have?', '[{"key":"A","text":"Zero"},{"key":"B","text":"One"},{"key":"C","text":"Two"},{"key":"D","text":"Infinitely many"}]'::jsonb, 'A', null, 'The discriminant b² − 4ac = 9 − 40 = −31 is negative, so there are no real solutions. Choice C is the usual guess for any quadratic, but a quadratic has two real solutions only when the discriminant is positive.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('af52386f-e79f-5ffb-a139-19fe28f56529', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 17, 'advanced_math', 'nonlinear_functions', 'hard', 'mc', null, 'The graph of the quadratic function f has its vertex at (1, −4). The function g is defined by g(x) = f(x − 3) + 2. What are the coordinates of the vertex of the graph of g?', '[{"key":"A","text":"(−2, −2)"},{"key":"B","text":"(4, −2)"},{"key":"C","text":"(4, −6)"},{"key":"D","text":"(−2, −6)"}]'::jsonb, 'B', null, 'Replacing x with x − 3 shifts the graph 3 units to the right, and adding 2 shifts it up 2, moving the vertex to (1 + 3, −4 + 2) = (4, −2). Choice A shifts left, the trap set by the minus sign inside the parentheses.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('dc591a78-b31b-5da7-a72b-c2a167f088eb', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 18, 'advanced_math', 'nonlinear_eq_systems', 'hard', 'spr', null, 'The system x² + y² = 25 and y = x + 1 has two solutions. What is the greater of the two x-coordinates?', null, '3', '["3.0"]'::jsonb, 'Substitute: x² + (x + 1)² = 25, so 2x² + 2x − 24 = 0, or x² + x − 12 = 0, which factors as (x + 4)(x − 3). The x-coordinates are −4 and 3, and the greater is 3. Dropping the (x + 1)² expansion''s middle term is the usual error.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('b3e44f17-3d1c-5f7c-aa75-b0361a83ad64', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 19, 'psda', 'two_var_data', 'hard', 'mc', null, 'Five students recorded the hours they studied for a test and their scores.
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('9ac428ec-56a8-58dc-a40b-1210cce8cf5e', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 20, 'psda', 'evaluating_claims', 'hard', 'mc', null, 'A researcher wants to estimate the mean daily commute time of the 200,000 workers in a city and plans to survey 500 of them. Which method of choosing the 500 workers is most likely to produce a sample that represents all workers in the city?', '[{"key":"A","text":"Selecting 500 workers at random from a list of all workers in the city"},{"key":"B","text":"Surveying 500 workers as they leave one downtown train station"},{"key":"C","text":"Posting an online survey and using the first 500 responses received"},{"key":"D","text":"Surveying 500 workers employed by the city''s largest company"}]'::jsonb, 'A', null, 'Only a random selection from the whole population gives every worker the same chance of being chosen. The other methods each favor one group, such as train commuters or one employer, so their mean would describe that group, not the city.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('b6732f48-0930-54a0-acdd-f6d4c8fed23b', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 21, 'geometry_trig', 'area_volume', 'hard', 'spr', null, 'A right circular cylinder has a volume of 500π cubic centimeters and a height of 20 centimeters. What is the radius of the cylinder, in centimeters?', null, '5', '["5.0"]'::jsonb, 'Volume is πr²h, so 500π = πr²(20); dividing by 20π gives r² = 25 and r = 5. Forgetting to take the square root gives 25.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('ac83140d-7144-5182-a748-8471641bb018', '40c5c5fa-8903-56f6-a97f-1e840fc6db88', 22, 'geometry_trig', 'right_triangles_trig', 'hard', 'mc', null, 'In a right triangle, one of the acute angles has measure θ, and cos θ = 7/25. What is the value of tan θ?', '[{"key":"A","text":"24/7"},{"key":"B","text":"7/24"},{"key":"C","text":"24/25"},{"key":"D","text":"25/7"}]'::jsonb, 'A', null, 'If the adjacent side is 7 and the hypotenuse is 25, the opposite side is √(625 − 49) = 24, so tan θ = opposite/adjacent = 24/7. Choice B inverts the ratio, and choice C is sin θ.') on conflict (id) do nothing;
